description:
Write `public static class Tags` with `public static List<string> Find(string text)` returning the hashtags in `text`: a `#` followed by one or more letters, digits or underscores, where the `#` is at the start or right after a character that is not a word character. Return them lower-cased, without the `#`, without duplicates, in order of first appearance.

```csharp
Tags.Find("Loving #CSharp and #regex! #csharp again, not a#tag, #c_sharp_12");
// ["csharp", "regex", "c_sharp_12"]
```

starter.Solution.cs:
public static class Tags
{
    public static List<string> Find(string text) =>
        text.Split(' ').Where(w => w.StartsWith('#')).ToList();
}

solution.Solution.cs:
using System.Text.RegularExpressions;

public static class Tags
{
    public static List<string> Find(string text)
    {
        var result = new List<string>();
        foreach (Match m in Regex.Matches(text, @"(?<!\w)#(\w+)"))
        {
            string tag = m.Groups[1].Value.ToLowerInvariant();
            if (!result.Contains(tag)) result.Add(tag);
        }
        return result;
    }
}

unitTests:
Test("tags", () =>
{
    CheckEq(Tags.Find("Loving #CSharp and #regex! #csharp again, not a#tag, #c_sharp_12"), new[] { "csharp", "regex", "c_sharp_12" });
    CheckEq(Tags.Find("#start,#end."), new[] { "start", "end" });
    CheckEq(Tags.Find("no tags # here"), new string[0]);
});

